def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '%': 2,
                  '~': 3, '^': 4}

    def apply() -> bool:
        op = operators.pop()
        if op == '~':
            values[-1] = -values[-1]
            return True

        b = values.pop()
        a = values.pop()

        if op == '+':
            result = a + b
        elif op == '-':
            result = a - b
        elif op == '*':
            result = a * b
        elif op == '^':
            if b < 0:
                return False
            result = pow(a, b)
        else:
            if b == 0:
                return False
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            result = quotient if op == '/' else a - b * quotient

        values.append(result)
        return True

    i = 0
    n = len(expr)
    expecting_operand = True

    while i < n:
        ch = expr[i]

        if ch.isspace():
            i += 1
            continue

        if '0' <= ch <= '9':
            end = i + 1
            while end < n and '0' <= expr[end] <= '9':
                end += 1

            # Small chunks avoid Python's decimal string conversion limit.
            number = 0
            while i < end:
                chunk_end = min(i + 9, end)
                number = number * (10 ** (chunk_end - i)) + int(expr[i:chunk_end])
                i = chunk_end

            values.append(number)
            expecting_operand = False
            continue

        if ch == '(':
            operators.append(ch)
            expecting_operand = True
        elif ch == ')':
            while operators[-1] != '(':
                if not apply():
                    return "error"
            operators.pop()
            expecting_operand = False
        elif ch == '-' and expecting_operand:
            # Prefix operators never reduce a pending power.
            operators.append('~')
        else:
            while operators and operators[-1] != '(':
                top_priority = precedence[operators[-1]]
                current_priority = precedence[ch]
                if top_priority < current_priority:
                    break
                if top_priority == current_priority and ch == '^':
                    break
                if not apply():
                    return "error"

            operators.append(ch)
            expecting_operand = True

        i += 1

    while operators:
        if not apply():
            return "error"

    return values[0]
